"""
ScholaCore Phase 3 -- Paystack payment page, HMAC-verified idempotent
webhook, single-use Telegram invite delivery, webhook fallback logging.

Additive on top of Phase 1 + Phase 2, already on `main`. Nothing is
deleted. Also updates:
  - src/pages/student-signup.ts (redirect target: /index.html -> /pay.html)
  - vite.config.ts (registers pay.html as a build entry point)
  - .env.example (adds TELEGRAM_CLASS_GROUP_CHAT_ID)
  - README.md (phase status + payment flow docs)

New required env var: TELEGRAM_CLASS_GROUP_CHAT_ID -- the chat ID of the
Telegram group students get a single-use invite link to after payment.
Set this in Vercel's Environment Variables before testing payments.

Note: api/_lib/telegramBot.ts uses Telegram's createChatInviteLink (with
member_limit: 1) rather than the exportChatInviteLink method named in the
original brief -- exportChatInviteLink can only re-export a chat's one
shared primary link and cannot be limited to a single use, so it can't
actually satisfy "single-use invite link". createChatInviteLink is the
correct call for that.

Run on your Windows machine with the repo already cloned.

Usage:
    python deploy_scholacore_phase3.py [path_to_repo]
"""
import base64, os, subprocess, sys

DEFAULT_REPO = r"C:\Users\Bosslady\SCHOLACORE\scholacore"

FILES = {
    'pay.html': '',
    'src/pages/pay.ts': '',
    'api/paystack-webhook.ts': '',
    'api/_lib/telegramBot.ts': '',
    'src/pages/student-signup.ts': '',
    'vite.config.ts': '',
    '.env.example': '',
    'README.md': '',
}


def run(cmd, cwd):
    print(">", " ".join(cmd))
    result = subprocess.run(cmd, cwd=cwd, capture_output=True, text=True)
    if result.stdout.strip():
        print(result.stdout)
    if result.returncode != 0 and result.stderr.strip():
        print(result.stderr)
    return result.returncode == 0


def main():
    repo_root = sys.argv[1] if len(sys.argv) > 1 else DEFAULT_REPO
    if not os.path.isdir(repo_root):
        print(f"Repo path not found: {repo_root}")
        sys.exit(1)
    if not os.path.isdir(os.path.join(repo_root, ".git")):
        print(f"{repo_root} is not a git repository (no .git folder). Aborting.")
        sys.exit(1)

    written = []
    for rel_path, b64_content in FILES.items():
        dest = os.path.join(repo_root, rel_path.replace("/", os.sep))
        os.makedirs(os.path.dirname(dest), exist_ok=True)
        with open(dest, "wb") as f:
            f.write(base64.b64decode(b64_content))
        written.append(rel_path)
        print(f"wrote: {rel_path}")

    print(f"\n{len(written)} files written to {repo_root}")

    if not run(["git", "add"] + written, repo_root):
        sys.exit(1)
    commit_msg = "Phase 3: Paystack payment page, HMAC-verified idempotent webhook, single-use Telegram invite delivery, fallback logging"
    if not run(["git", "commit", "-m", commit_msg], repo_root):
        print("Nothing to commit or commit failed -- check output above.")
        sys.exit(1)
    run(["git", "push", "origin", "main"], repo_root)

    print("\nReminder: set these in Vercel's Environment Variables before testing payments:")
    print("  - PAYSTACK_SECRET_KEY")
    print("  - VITE_PAYSTACK_PUBLIC_KEY")
    print("  - TELEGRAM_BOT_TOKEN")
    print("  - TELEGRAM_CLASS_GROUP_CHAT_ID  (new in this phase)")
    print("  - FIREBASE_SERVICE_ACCOUNT_KEY")
    print("Also register the webhook URL in your Paystack dashboard:")
    print("  https://<your-vercel-domain>/api/paystack-webhook")


if __name__ == "__main__":
    main()
